#include <vector>
#include <algorithm>

class Solution {
public:
    int maxBalancedShipments(std::vector<int>& weights) {
        int count = 0;
        int current_max = -1;

        for (int w : weights) {
            if (current_max == -1) {
                current_max = w;
            } else {
                current_max = std::max(current_max, w);
                if (w < current_max) {
                    count++;
                    current_max = -1;
                }
            }
        }
        return count;
    }
};

class Solution {
    public int maxBalancedShipments(int[] weights) {
        int count = 0;
        int currentMax = -1;

        for (int w : weights) {
            if (currentMax == -1) {
                currentMax = w;
            } else {
                currentMax = Math.max(currentMax, w);
                if (w < currentMax) {
                    count++;
                    currentMax = -1;
                }
            }
        }
        return count;
    }
}

var maxBalancedShipments = function(weights) {
    let count = 0;
    let currentMax = -1;

    for (const w of weights) {
        if (currentMax === -1) {
            currentMax = w;
        } else {
            currentMax = Math.max(currentMax, w);
            if (w < currentMax) {
                count++;
                currentMax = -1;
            }
        }
    }
    return count;
};
